import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"D3.4 · 高风险 GUI 与 Stage 3 发布","description":"Hearth D3.4 开发增量：用户对不可逆或高影响桌面动作看到完整影响、二次确认和补偿方式；失败后不会留下未知的高风险状态。","frontmatter":{"title":"D3.4 · 高风险 GUI 与 Stage 3 发布","description":"Hearth D3.4 开发增量：用户对不可逆或高影响桌面动作看到完整影响、二次确认和补偿方式；失败后不会留下未知的高风险状态。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-3/d3-4.md","filePath":"delivery/stage-3/d3-4.md","lastUpdated":null}'),r={name:"delivery/stage-3/d3-4.md"};function s(d,a,o,h,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 3 · D3.4 · 4 / 4</p><h1 id="d3-4-·-高风险-gui-与-stage-3-发布" tabindex="-1">D3.4 · 高风险 GUI 与 Stage 3 发布 <a class="header-anchor" href="#d3-4-·-高风险-gui-与-stage-3-发布" aria-label="Permalink to &quot;D3.4 · 高风险 GUI 与 Stage 3 发布&quot;">​</a></h1><p class="lead">对不可逆或高影响的桌面动作建立完整影响说明、隔离执行、二次确认和补偿路径，然后才发布桌面操作员。</p><p class="page-meta">STAGE 3 · D3.4 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>用户对不可逆或高影响桌面动作看到完整影响、二次确认和补偿方式；失败后不会留下未知的高风险状态。</div><div><strong>完成门槛</strong>至少 5 个代表性桌面任务完成；接管和高风险审批可用；无密码库/系统设置越权；失败不留半完成高风险状态；用户理解如何撤销或补偿。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>用户对不可逆或高影响桌面动作看到完整影响、二次确认和补偿方式；失败后不会留下未知的高风险状态。</p><p>Stage 3 的顺序是观察、接管、低风险动作、高风险动作；无法观察和接管的桌面自动化不具备产品资格。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>Stage 1–2 的恢复、审批、幂等、回执和网页隔离已经稳定。</li><li>有一台可配对的专用桌面设备，明确哪些窗口、应用和文件范围允许操作。</li><li>GUI 任务可以在隔离桌面中运行，且用户能随时暂停和接管。</li><li>D3.3 的交付物已经验收；未通过时不进入本增量。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-隔离桌面与快照" tabindex="-1">01 · 隔离桌面与快照 <a class="header-anchor" href="#_01-·-隔离桌面与快照" aria-label="Permalink to &quot;01 · 隔离桌面与快照&quot;">​</a></h3><p>在隔离虚拟桌面中执行不可逆或高影响任务，限制网络、共享目录和外设，开始前创建可恢复快照。任务结束或失败后保留快照和动作日志，用户确认影响后再销毁；隔离边界不能成为绕过审批的理由。</p><h3 id="_02-·-不可逆动作清单与风险矩阵" tabindex="-1">02 · 不可逆动作清单与风险矩阵 <a class="header-anchor" href="#_02-·-不可逆动作清单与风险矩阵" aria-label="Permalink to &quot;02 · 不可逆动作清单与风险矩阵&quot;">​</a></h3><p>列出删除、覆盖、发送、支付、权限修改和公开发布等不可逆动作，按影响范围、可补偿性和可观察性分级。每级规定审批、二次确认、快照、人工在场或禁止执行；高风险动作不得在无人值守的主动循环中运行。</p><h3 id="_03-·-影响预览与二次确认" tabindex="-1">03 · 影响预览与二次确认 <a class="header-anchor" href="#_03-·-影响预览与二次确认" aria-label="Permalink to &quot;03 · 影响预览与二次确认&quot;">​</a></h3><p>Effect Preview 展示目标、真实参数、预期结果、不可逆部分、补偿脚本和失败后的停留状态。执行前要求与参数绑定的二次确认，过期、参数变化或设备变化都使确认失效；用户必须能读懂影响，而不是只看到“继续”。</p><h3 id="_04-·-失败演练与-stage-3-发布" tabindex="-1">04 · 失败演练与 Stage 3 发布 <a class="header-anchor" href="#_04-·-失败演练与-stage-3-发布" aria-label="Permalink to &quot;04 · 失败演练与 Stage 3 发布&quot;">​</a></h3><p>注入窗口崩溃、网络断开、快照失败、半完成和接管中断，验证失败后不留未知高风险状态。至少完成 5 个代表性桌面任务并覆盖接管、高风险审批和恢复；发布说明列明禁止应用、不可逆边界和人工兜底方式。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>apps/agentd</code> — 设备配对、能力声明、健康检查与撤销</li><li><code>packages/devices</code> — 设备身份、会话、能力目录与在线状态</li><li><code>packages/desktop-observation</code> — 窗口边界、截图、可访问性树与脱敏</li><li><code>packages/desktop-control</code> — 白名单、定位器、输入动作与前后条件</li><li><code>packages/desktop-verification</code> — 截图比较、焦点检查、半完成检测</li><li><code>packages/approval</code> — 桌面 Effect Preview、二次确认与补偿说明</li><li><code>apps/web</code> — 设备页、观察视图、实时接管和恢复界面</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>DeviceManifest</code></td><td>deviceId、publicKey、agentdVersion、capabilities、allowedRoots、expiresAt、revocationState；未声明的能力不可调用。</td></tr><tr><td><code>ObservationFrame</code></td><td>captureId、windowBounds、screenshotRef、accessibilityTree、capturedAt、redactions；只采集完成任务所需的最小范围。</td></tr><tr><td><code>DesktopAction</code></td><td>actionType、targetWindow、locator、preconditions、expectedPostconditions、riskLevel、timeout；执行前必须通过策略检查。</td></tr><tr><td><code>DesktopReceipt</code></td><td>actionId、beforeRef、afterRef、verification、partialState、compensation、approvalId；失败时保留可恢复证据。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:device：配对、能力越权、离线、撤销和会话失效</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:desktop：观察、接管、焦点变化、半完成和补偿</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:desktop-fault：窗口漂移、元素消失、输入争抢和崩溃</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:computer：至少</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 个真实桌面任务及失败样本</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-3/d3-4.html">D3.4 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：隔离桌面与快照、不可逆动作清单与风险矩阵、影响预览与二次确认、失败演练与 Stage 3 发布。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“窗口或元素不匹配”。页面必须显示“任务暂停并显示当前窗口截图和需要确认的元素。”，然后按“重新定位、请求接管或调整白名单，不盲目点击坐标。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：至少 5 个代表性桌面任务完成；接管和高风险审批可用；无密码库/系统设置越权；失败不留半完成高风险状态；用户理解如何撤销或补偿。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>隔离虚拟桌面</li><li>高风险审批与动作清单</li><li>快照/补偿/恢复演练</li><li>5 个真实桌面任务</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 至少 5 个代表性桌面任务完成；接管和高风险审批可用；无密码库/系统设置越权；失败不留半完成高风险状态；用户理解如何撤销或补偿。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>窗口或元素不匹配</td><td>任务暂停并显示当前窗口截图和需要确认的元素。</td><td>重新定位、请求接管或调整白名单，不盲目点击坐标。</td></tr><tr><td>自动输入与用户争抢</td><td>自动输入立即暂停，控制权交给用户。</td><td>等待用户交还并确认焦点、窗口和下一步。</td></tr><tr><td>高风险动作半完成</td><td>任务显示“需要检查”，隐藏继续按钮并保留快照。</td><td>按补偿脚本或人工接管恢复，记录未完成影响。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不在无法观察、无法验证或无法接管时开放自动操作。</li><li>不读取密码库，不修改系统安全设置，不操作未授权窗口。</li><li>不把一次成功的坐标点击当成通用 GUI 能力。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/architecture/human-takeover.html">人工接管与审批</a></li><li><a href="/hearth-os/architecture/execution-safety.html">执行安全与副作用</a></li><li><a href="/hearth-os/architecture/executor-catalog.html">执行器目录</a></li><li><a href="/hearth-os/architecture/frontend-experience.html">前端与移动体验</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>返回 <a href="/hearth-os/delivery/stage-3.html">Stage 3 · Computer Operator</a>，确认全部退出条件后进入 <a href="/hearth-os/delivery/stage-4.html">Stage 4</a>。</p>`,42)])])}const k=e(r,[["render",s]]);export{u as __pageData,k as default};
